import{z as i,x as o,o as B,c as p,q as r,j as l,D as E,d as s,s as A,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"B+ 分裂与合并","description":"","frontmatter":{"title":"B+ 分裂与合并","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bplus-split.md","filePath":"cs/bplus-split.md","lastUpdated":1791413859000}'),d={name:"cs/bplus-split.md"};function m(C,a,h,u,D,F){const t=o("Mermaid");return B(),p("div",null,[a[2]||(a[2]=r('<h1 id="b-分裂与合并" tabindex="-1">B+ 分裂与合并 <a class="header-anchor" href="#b-分裂与合并" aria-label="Permalink to &quot;B+ 分裂与合并&quot;">​</a></h1><div class="epigraph"><p>叶满则分裂并向上插分隔键；欠载则与兄弟合并或再分配，树保持矮而平衡。</p><footer>—— 据 Comer, The Ubiquitous B-Tree；Ramakrishnan and Gehrke 对 B+ 维护的整理</footer></div><p><a href="/cs/bplus-index">上一课</a>给出 B+：内节点指路，叶拉成链表。本课不重画查找。缺口是更新：插入使叶溢出，删除使叶过空。分裂/合并沿祖先传递，可能加高树。哈希索引下一课才对照等值路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>B+ 课留下静态结构。数据库的插入删除是常态。叶分裂：一半键留下，一半到新页，父节点插入分隔键；父满则继续裂。根裂则长高一层。合并是逆操作，常设低水位以免振荡。缺口是<strong>维持占用率与平衡的机制</strong>，与内存 <a href="/cs/avl-rotate">AVL 旋转</a> 同目标、另一套页 I/O。</p><p><span class="marginnote">右分隔键的复制还是上移，实现有变体。并发下要锁住祖先或用锁耦合，后课库内锁再谈，本课先串行维护。</span></p><p><span class="marginnote">术语翻译：<strong>写放大</strong>=逻辑上改一条记录，磁盘上却要写好几页。叶分裂时本页、新页、父页、直到祖先都得动一趟——本来 1 页的事放大成 4、5 页的写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入：找到叶，有空槽则插；否则裂。删除：叶内删，过空则借或并。范围扫描沿叶链走，分裂时必须同时维护兄弟指针。聚簇索引上分裂会移动行，rid 若按页槽则要稳定策略（前课页与槽）。</p>',9)),(B(),l(n,null,{default:E(()=>[A(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%E6%BA%A2%E5%87%BA%22%5D%20--%3E%20SPLIT%5B%22%E5%8F%B6%E8%A3%82%E5%B9%B6%E5%90%91%E7%88%B6%E6%8F%92%E9%94%AE%22%5D%0A%20%20SPLIT%20--%3E%20UP%5B%22%E5%8F%AF%E8%83%BD%E4%B8%80%E7%9B%B4%E8%A3%82%E5%88%B0%E6%A0%B9%22%5D%0A%20%20DEL%5B%22%E5%88%A0%E9%99%A4%E6%AC%A0%E8%BD%BD%22%5D%20--%3E%20MERGE%5B%22%E4%B8%8E%E5%85%84%E5%BC%9F%E5%90%88%E5%B9%B6%E6%88%96%E5%86%8D%E5%88%86%E9%85%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"分裂把一次插入的 I/O 从「改一页」变成「改一串祖先」，这是 B+ 写放大的来源。WAL 后课会把这些页改写进日志。查找高度仍是对数，因为裂是平衡的。覆盖扫描在叶上走，会看见分裂中的短暂不一致——并发协议后补。",-1)),a[5]||(a[5]=e("p",null,"一次叶分裂具体怎么切？看页满之后的三步：",-1)),(B(),l(n,null,{default:E(()=>[A(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%22%E5%8F%B6%E9%A1%B5%E6%BB%A1%EF%BC%9A10%2C20%2C30%2C40%EF%BC%9B%E6%8F%92%E5%85%A5%2025%20%E5%90%8E%E6%BA%A2%E5%87%BA%22%5D%20--%3E%20H%5B%22%E5%AF%B9%E5%8D%8A%E5%88%86%EF%BC%9A%E6%97%A7%E9%A1%B5%E7%95%99%203%20%E4%B8%AA%20%E6%96%B0%E9%A1%B5%202%20%E4%B8%AA%22%5D%0A%20%20H%20--%3E%20A%5B%22%E6%97%A7%E9%A1%B5%EF%BC%9A10%2C20%2C25%E3%80%80%E6%96%B0%E9%A1%B5%EF%BC%9A30%2C40%22%5D%0A%20%20A%20--%3E%20UP%5B%22%E5%88%86%E9%9A%94%E9%94%AE%2030%20%E6%8B%B7%E8%B4%9D%E8%BF%9B%E7%88%B6%E8%8A%82%E7%82%B9%22%5D%0A%20%20UP%20--%3E%20FULL%7B%22%E7%88%B6%E8%8A%82%E7%82%B9%E4%B9%9F%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20FULL%20--%3E%7C%22%E6%98%AF%22%7C%20CASC%5B%22%E7%88%B6%E7%BB%A7%E7%BB%AD%E5%88%86%E8%A3%82%EF%BC%8C%E7%BA%A7%E8%81%94%E5%90%91%E4%B8%8A%22%5D%0A%20%20FULL%20--%3E%7C%22%E5%90%A6%22%7C%20DONE%5B%22%E7%BB%93%E6%9D%9F%EF%BC%9A%E6%A0%91%E9%AB%98%E4%B8%8D%E5%8F%98%22%5D%0A%20%20CASC%20--%3E%20ROOT%5B%22%E6%A0%B9%E8%A3%82%E5%88%99%E6%95%B4%E6%A0%91%E9%95%BF%E9%AB%98%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：一页放 4 个键，插入第 5 个就裂成 3 个与 2 个两页，新页占用率只剩一半。所以工程上常用「裂之前先试兄弟、或裂成 60/40」来减少这种半空页——纯对半裂是教学版。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 B-link 树的全部无锁方案写入主干。等值点查询若不需要范围，哈希索引是另一结构，下一课。</p><p>后课默认：B+ 在更新下保持平衡。等值可用哈希路径。</p><p><span class="marginnote">常见误区：初学者容易以为删几条数据树会立刻「缩矮」。合并有低水位门槛，且实践中常惰性标删不合并——马上删马上并，随后又插入，页就会反复裂并（振荡），白写一倍 I/O。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>溢出分裂、欠载合并，树保持平衡。</li><li>写放大来自祖先链。</li><li>哈希索引下一课。</li><li>出处：Comer, <em>CSUR</em> 1979；Ramakrishnan and Gehrke。</li></ul>',7))])}const _=i(d,[["render",m]]);export{f as __pageData,_ as default};
